INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('ifc-news', 'IFC News', 'AI · Fintech media', 'AI-powered financial news & investment platform.', 'An AI-powered financial platform designed to bridge the gap between complex market data and actionable investment intelligence for emerging investors.', 'A digital financial platform that helps users discover, understand, and analyze financial market information through news, market insights, and AI-powered features.', 'Product & Project Manager', 'Set up the development process and product roadmap, then pulled the growth levers — SEO, infrastructure cost, payments and a freemium tier.', 'PT InfantAI Teknologi Nusantara', '2025 — 2026', 'https://ifcnews.id', 'projects/ifc-news/home.webp', 'IFC News homepage: Indonesian markets, decoded by AI', 'light', '[{"value":"224k","label":"Total impressions"},{"value":"945","label":"Total clicks"},{"value":"15k","label":"Peak daily impressions"},{"value":"64","label":"Peak daily clicks"}]', '[{"title":"Financial News","body":"Indonesian market news with real-time translation into the reader''s language."},{"title":"AI-Powered Insights","body":"AI summaries and sentiment on every story, alongside revenue, net profit and market cap."},{"title":"Stock Picks & Weekly Analysis","body":"A daily top pick with target price and stop-loss, plus market sentiment and weekly analysis."},{"title":"Personalized Interests","body":"A feed shaped around each reader''s financial interests."}]', '[]', '[{"title":"Process & organic growth","challenge":["No structured **SDLC** was in place.","Development was handled based on immediate needs, **without standardized processes, planning, or systems**.","**Organic traffic was at zero.**"],"responsibilities":["Built a structured **development process**.","Improved **SEO performance** in less than 1 month.","Developed the product **roadmap**."],"initiatives":["Implemented **Scrum & Sprint Planning**.","Managed **Backlog & Roadmap**.","Optimized **SEO foundations**.","Presented and pitched **IFCNews** at ITB."],"impact":["**SEO** was completed **~20 days ahead of schedule**.","**Scrum** became the team''s standard working process.","**Premium Subscription roadmap** was structured for the next 4 sprints."]},{"title":"Cost efficiency & monetization","challenge":["**High operational costs** due to dependency on Railway hosting.","**No payment gateway integration** for direct user transactions.","**No freemium scheme** to support marketing and user acquisition strategies."],"responsibilities":["**Reduced costs** and improved platform operational efficiency.","Led the **payment gateway implementation** for user transactions.","**Aligned the freemium scheme** with marketing acquisition targets."],"initiatives":["**Migrated the server** from Railway to an **independent VPS**.","**Reduced server workload** to lower monthly operational costs.","Implemented **payment gateways** via Pakasir and Saweria.","Launched **a freemium model** to accelerate user acquisition."],"impact":["**~66% expense efficiency** — operational costs cut from $150 to $50/month through controlled resource management.","**Secure payment gateway** integration to support transactions and recurring revenue.","Accelerated new user acquisition and marketing conversion through access to basic features (**Freemium Model**)."]}]', '[{"src":"projects/ifc-news/news-stream.webp","alt":"IFC News news stream with AI summaries and sentiment","caption":"News Stream — AI summaries, sentiment and fundamentals on every story."},{"src":"projects/ifc-news/search-console.webp","alt":"Google Search Console performance chart for ifcnews.id","caption":"Google Search Console, 3-month view (June 2026)."},{"src":"projects/ifc-news/sprint-board.webp","alt":"IFC News development board on GitHub Projects","caption":"The sprint board on GitHub Projects."},{"src":"projects/ifc-news/team.webp","alt":"The IFC News team in a working session","caption":"Working session with the IFC News team."}]', 0);
INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('satglow-erp', 'Satglow ERP', 'ERP · Operations', 'Warehouse & operations management system.', 'An integrated ERP solution designed to centralize multi-warehouse inventory, streamline operational work orders, and automate real-time stock deductions across event transactions.', 'A centralized ERP system for Satellite of Glow to manage inventory across multiple warehouses, work orders, stock movements, and event cashier transactions.', 'Project Manager', 'Led the ERP implementation — a flexible development process, validated user requirements and a product roadmap.', 'PT InfantAI Teknologi Nusantara', '2026', NULL, 'projects/satglow-erp/dashboard.webp', 'Satglow ERP warehouse dashboard', 'light', '[]', '[{"title":"Multi-Warehouse Inventory","body":"One inventory across every warehouse, with vendors and warehouse transfers."},{"title":"Work Orders","body":"Create and track operational work orders."},{"title":"Stock Movements","body":"Track stock movements and inventory levels, down to barcode scans and checkouts."},{"title":"Event Cashier","body":"Cashier transactions with real-time stock sync and automatic receipts."}]', '[]', '[{"title":"Built from scratch","challenge":["The system was **developed from scratch**.","**Requirements** changed according to user needs.","There was no established **development lifecycle**."],"responsibilities":["Established a flexible **development process**.","Ensured that **user requirements** were validated.","Developed a **product roadmap**."],"initiatives":["**RAD method**: Requirement Planning, User Design, iterative Construction.","**Roadmap**: Division Master, Excel Engine, Batch Inventory, Expired Batching."],"impact":["**DB refactor** completed **~3 weeks ahead of schedule**.","**Development lifecycle** became more structured.","**Requirements** became easier to validate."]}]', '[]', 1);
INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('nordpartners', 'NordPartners', 'PropTech · Partnerships', 'Melbourne property partnership platform.', 'A digital partnership platform designed to connect investors with Melbourne property opportunities, streamlining the end-to-end journey from user onboarding and admin approval to QR-verified event access.', 'NordPartners is a digital platform designed to support property partnership activities in Melbourne, connecting participants with property opportunities and managing the registration and approval process.', 'Project & Product Manager', 'Managed requirements, priorities, stakeholder coordination, and development delivery.', NULL, NULL, 'https://nordpartners.id', 'projects/nordpartners/home.webp', 'NordPartners homepage: strategic access to Australian property and investment opportunities', 'dark', '[{"value":"~5 days","label":"Delivered ahead of schedule"},{"value":"0","label":"Implementation issues at go-live"}]', '[{"title":"Property Opportunity & Registration","body":"Present Melbourne property opportunities to participants. Manages user registration and participation flow from initial sign-up through onboarding."},{"title":"Verification & Admin Approval","body":"Email verification for registered users ensures authenticity. Admin reviews and approves participants before granting access to property events."},{"title":"Event Access Management","body":"QR-based access system for approved participants at property events. Streamlines entry and ensures only verified, approved users gain access."}]', '[{"title":"Key value","steps":["Property opportunity","Registration","Verification","Approval","Event"]}]', '[{"title":"Shipping while requirements move","challenge":["**Requirements** evolved according to **stakeholder needs**."],"responsibilities":["Ensured delivery remained aligned with the **target** and **stakeholder expectations**."],"initiatives":["Used the **RAD** methodology.","Managed **requirements** and development **priorities**.","**Coordinated** the delivery of the KCL × NØRD module.","Developed a **conversion monitoring roadmap**."],"impact":["Delivery was completed approximately **5 days ahead of schedule**.","**Zero implementation issues** during go-live."]}]', '[]', 2);
INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('nose-one', 'NOSE ONE', 'ERP · HRIS', 'Integrated factory management platform — NOSE HRIS.', 'A centralized HRIS module within a comprehensive factory ERP platform, built to unify employee data, complex attendance shifts, payroll, and talent acquisition into a single operational hub.', 'NOSE ONE is an integrated system that connects multiple factory divisions into one centralized platform. I managed the HRIS scope, focusing on employee management, attendance, payroll, and talent operations.', 'Project Manager', 'Managed HRIS requirements, priorities, workflow design, stakeholder coordination & delivery.', 'PT Nose Herbal Indo', '2026', NULL, 'projects/nose-one/dashboard.webp', 'NOSE ONE HRIS dashboard', 'light', '[]', '[{"title":"People","body":"Employees, organization and manpower."},{"title":"Attendance","body":"Shifts, overtime, leave and compliance."},{"title":"Payroll","body":"Payroll management."},{"title":"Talent","body":"Recruitment and onboarding."}]', '[{"title":"Key value","steps":["One system","Centralized HR data","Integrated HR operations","Better management visibility"]}]', '[]', '[]', 3);
INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('aix-expo', 'AIX Expo', 'Events · AI', 'AI summit & exhibition platform.', 'An integrated event and exhibition platform built to connect global tech enterprises, industry professionals, and attendees through curated AI showcases, summits, and business matchmaking.', 'AIX Expo is a digital platform supporting an AI-focused summit and exhibition, connecting technology companies, businesses, professionals, creators, and visitors through an integrated event experience.', 'Project Manager', 'Managed project requirements, priorities, stakeholder coordination, and development delivery.', NULL, '2026', NULL, 'projects/aix-expo/home.webp', 'AIX Indonesia homepage: Indonesia''s premier AI Summit', 'dark', '[]', '[{"title":"AI Exhibition","body":"Showcase AI technologies and solutions."},{"title":"Summit","body":"Support AI-focused discussions and sessions."},{"title":"Business Connection","body":"Connect companies and potential partners."},{"title":"Visitor Experience","body":"Provide information and access to the event."}]', '[{"title":"Ecosystem","steps":["Technology companies","AIX Expo","Businesses & professionals","Visitors"]},{"title":"Key value","steps":["AI technology","Exhibition","Connection","Experience"]}]', '[]', '[]', 4);
INSERT INTO projects (slug, name, category, tagline, summary, description, role, role_detail, company, year, url, cover_key, cover_alt, theme, metrics, modules, flows, stories, gallery, sort) VALUES ('genius-ai', 'Genius AI', 'AI hardware · EdTech', 'A conversational learning companion for kids.', 'An interactive AI-powered educational device that bridges embedded hardware and top-tier LLMs to create an engaging, child-friendly conversational learning experience.', 'Part of InfantAI''s early-education line: a compact companion device that pairs embedded hardware with top-tier LLMs, so children learn through natural conversation.', 'Product & Project Manager', 'One of the concurrent InfantAI product lines in my portfolio.', 'PT InfantAI Teknologi Nusantara', '2025 — 2026', NULL, 'projects/genius-ai/devices.webp', 'Genius AI devices in green dinosaur and pink bunny cases', 'light', '[]', '[{"title":"Embedded hardware","body":"A compact device with its own screen, dressed in playful cases."},{"title":"Top-tier LLMs","body":"Conversations powered by leading large language models."},{"title":"Built for children","body":"An engaging, child-friendly way to learn by talking."}]', '[]', '[]', '[]', 5);
INSERT INTO experience (company, company_note, role, location, start_date, end_date, summary, points, sort) VALUES ('PT InfantAI Teknologi Nusantara', 'PT Nose Herbal Indo', 'Product & Project Manager', 'Shenzhen, Guangdong, China', 'Sep 2025', 'Present', 'AI-focused startup building digital products for parenting, early education and financial news — Infant.AI, GeniusAI and IFCNews.', '["Led end-to-end software development — requirements, planning, development, QA, deployment and post-release optimization.","Managed a cross-functional team of 10 engineers and IT professionals across Frontend, Backend, QA, Business Analysis, Marketing, UI/UX and IT Support.","Defined product requirements, user stories, acceptance criteria, scope, milestones and backlogs from business requirements and technical feasibility.","Managed roadmaps, priorities, schedules, resources, risks and stakeholder communication across multiple concurrent projects.","Implemented Role-Based Access Control (RBAC) to enforce role-specific permissions.","Led the ERP implementation for Satglow Invent — multi-warehouse inventory and operational workflows.","Led a payment gateway implementation supporting multiple providers.","Migrated from Railway to self-managed VPS infrastructure, including the stack and database, while keeping the system available.","Cut monthly operating expenses from ~$150 to ~$50 through the VPS migration and LLM API token optimization.","Launched a freemium model to support marketing, user acquisition and conversion.","Drove product improvements from user feedback, business priorities, technical constraints and product performance.","Set up project monitoring and development workflows for visibility across engineering and cross-functional teams."]', 0);
INSERT INTO experience (company, company_note, role, location, start_date, end_date, summary, points, sort) VALUES ('PT Rekadia Solusi Teknologi', NULL, 'Project Manager', 'AIA Central, Jakarta', 'Apr 2026', 'Aug 2026', 'Indonesian IT company specializing in software development, system integration and digital transformation.', '["Managed software development projects from planning to deployment.","Coordinated with clients to gather and define business requirements.","Planned project schedules and monitored progress to ensure timely delivery.","Collaborated with developers, QA engineers, UI/UX and stakeholders throughout the project lifecycle.","Prepared project documentation and ensured deliverables met quality standards."]', 1);
INSERT INTO experience (company, company_note, role, location, start_date, end_date, summary, points, sort) VALUES ('PT Super Pasar Rakyat Indonesia', 'BRI Group', 'Software Engineer', 'Central Jakarta', 'Feb 2025', 'Oct 2025', 'PARI — BRI Group''s digital marketplace for agricultural commodities, supporting farmers, breeders, fishermen and micro-entrepreneurs.', '["Acted as a cross-functional intern across product management, project coordination, full-stack development and QA in Agile sprints.","Supported financial features — TopUp, Withdrawal and Settlement — with Laravel, MySQL, Docker and Redis.","Managed sprint tasks, timelines and communication across product, design and engineering.","Designed, tested and optimized modules through structured QA, performance tuning and user feedback analysis."]', 2);
INSERT INTO experience (company, company_note, role, location, start_date, end_date, summary, points, sort) VALUES ('Moodscape', NULL, 'IT Product & Project Manager', 'South Jakarta', 'Jan 2024', 'Dec 2024', 'Kemendikbudristek-funded mental health innovation — an AI-powered app that monitors emotional well-being using graphology, facial recognition and machine learning.', '["Led roadmap planning, feature prioritization, backlog management and sprint execution with Agile Scrum.","Worked with developers and UI/UX designers on machine-learning mood analysis features.","Ran usability testing with 50+ users to improve the product experience.","Tracked progress and requirements in Jira, Confluence and Notion.","Secured full funding from Kemendikbudristek and earned national recognition in mental health technology."]', 3);
INSERT INTO education (school, degree, location, period, gpa, honor, image_key, image_alt, points, sort) VALUES ('Universitas Siber Indonesia', 'Bachelor of Information Technology (S.Kom)', 'TB Simatupang, South Jakarta', 'Sep 2022 — Sep 2026', '3.97', 'Best Graduate', 'education/graduation.webp', 'Raden Issa at the Universitas Siber Indonesia graduation ceremony, wearing the Lulusan Terbaik (Best Graduate) sash and holding the award certificate, with his family', '["Best Graduate (Wisudawan Terbaik) of the Information Technology program at the university''s 4th graduation ceremony, with a 3.97 GPA.","Full-ride scholarship — 100% tuition for four years, awarded for academic performance and leadership.","1st Place, Cyber Entrepreneur Product Innovation Competition — a Raspberry Pi and Nextcloud private cloud for SMEs and households.","Published research on private cloud storage with OwnCloud and Ubuntu Linux (Google Scholar).","Published research on MSME growth prediction in West Java using linear regression (Google Scholar).","Designed an IoT environmental monitoring system with NodeMCU, gas and climate sensors for real-time hazard alerts.","Speaker at a Data Security Awareness Program for 50+ participants."]', 0);
INSERT INTO organizations (name, role, location, period, summary, points, sort) VALUES ('Himpunan Mahasiswa Teknologi Informasi', 'President', 'Jakarta', 'Jul 2023 — Present', 'Leading the Information Technology Student Association''s academic and social programs.', '["Organized company visits to XL Axiata and Allo Bank.","Led community service on digital literacy and cybersecurity awareness.","Brought members together through workshops, internal projects and networking events."]', 0);
INSERT INTO organizations (name, role, location, period, summary, points, sort) VALUES ('Decompe 3.0', 'IT Infrastructure', 'Jakarta', 'Aug 2023 — Jan 2024', 'A national UI/UX design competition organized by Cyber University.', '["Ran IT infrastructure for 100+ participants from 10+ universities.","Kept 100% uptime through presentations and judging.","Built the registration and data system that sped up participant verification by 40%.","Resolved on-site and remote issues in about 5 minutes on average."]', 1);
